/** Stable PL slugs also survive translation of project type labels inside JSON. */
function zp_industry_work_project_slugs_20261015($projects, $mode = ''): array {
    if (!is_array($projects)) { return []; }
    $types = ['natalia arciszewska'=>'Logo + mini branding','piotr mazur'=>'Logo + identyfikacja','medical friend'=>'Logo + identyfikacja','gravia'=>'Strona firmowa + Kariera','zgorecki nieruchomosci'=>'Logo + mini branding','pracownia urody'=>'Logo + identyfikacja','arcyciecie'=>'Logo + identyfikacja','krawiec z dojazdem'=>'System + Rebranding','piekarnia marysia'=>'Strona lokalna','eat tasty'=>'Logo + identyfikacja','mona cake'=>'Logo + identyfikacja','apartament piekna'=>'Strona + Rezerwacje + SEO'];
    foreach ($projects as &$row) {
        if (!is_array($row) || empty($row['brand'])) { continue; }
        $brand = strtolower(remove_accents(trim((string) $row['brand']))); $cat = (string) ($row['cat'] ?? ($mode === 'logo' ? 'branding' : 'web'));
        $branding = strpos($cat, 'branding') !== false && strpos($cat, 'web') === false;
        $type = $types[$brand] ?? '';
        if ($brand === 'siemianowski') { $type = $branding ? 'Logo + branding premium' : 'Kancelaria premium / prawo i restrukturyzacja'; }
        if ($brand === 'polerstone') { $type = $branding ? 'Logo + identyfikacja' : 'Branding + strona firmowa'; }
        if ($type !== '') { $row['project_slug'] = substr(sanitize_title($row['brand'] . '-' . $type), 0, 90); }
    }
    unset($row); return $projects;
}
add_filter('zp_portfolio_projects_20261015', 'zp_industry_work_project_slugs_20261015', 5, 2);

function zp_industry_work_source_20261015(): string {
    if (class_exists('ZPL\\Router') && \ZPL\Router::$source !== '') { return (string) \ZPL\Router::$source; }
    return function_exists('zp_seo_plan_path') ? zp_seo_plan_path((string) get_permalink(get_queried_object_id())) : '';
}
function zp_industry_work_url_20261015(string $path, bool $english): string {
    return function_exists('zpl_url') ? zpl_url(home_url($path), $english ? 'en' : 'pl') : home_url($path);
}
function zp_industry_work_markup_20261015(string $source, bool $english): string {
    $spec = zp_industry_work_plan_20261015()[$source] ?? null;
    if (!$spec || !function_exists('zp_suite_realizacje_projects')) { return ''; }
    $lang = $english ? 'en' : 'pl'; $cards = ''; $projects = zp_suite_realizacje_projects(); $index = 0;
    $heading = esc_html($spec['title'][$lang]); $accent = (string) ($spec['title_accent'][$lang] ?? '');
    if ($accent !== '' && substr_count($spec['title'][$lang], $accent) === 1) { $heading = str_replace(esc_html($accent), '<strong>' . esc_html($accent) . '</strong>', $heading); }
    foreach ($spec['items'] as $item) {
        $found = null;
        foreach ($projects as $project) {
            $brand = strtolower(remove_accents((string) ($project['brand'] ?? ''))); $cat = (string) ($project['cat'] ?? '');
            if ($brand !== strtolower(remove_accents($item['brand']))) { continue; }
            if ($item['profile'] === 'web' && strpos($cat, 'web') === false) { continue; }
            if ($item['profile'] === 'branding' && (strpos($cat, 'branding') === false || strpos($cat, 'web') !== false)) { continue; }
            $found = $project; break;
        }
        if (!$found || empty($found['img']) || empty($found['project_slug'])) { continue; }
        $url = (string) ($found['case_url'] ?? '');
        if ($url === '') { $url = zp_industry_work_url_20261015('/realizacje/', $english) . '#case-' . $found['project_slug']; }
        $index++; $kind = $item['profile'] === 'branding' ? ($english ? 'Branding project' : 'Projekt brandingowy') : ($english ? 'Website project' : 'Projekt strony');
        $cards .= '<article class="zpIndustryWork__card" data-zp-project="' . esc_attr($found['project_slug']) . '"><a class="zpIndustryWork__visual" href="' . esc_url($url) . '" aria-label="' . esc_attr(($english ? 'Explore ' : 'Zobacz ') . $item['brand']) . '"><img src="' . esc_url($found['img']) . '" alt="' . esc_attr($item['brand'] . ' — ' . $item['scope'][$lang]) . '" width="1600" height="1067" loading="lazy" decoding="async"><span>' . sprintf('%02d', $index) . '</span></a><div class="zpIndustryWork__body"><p class="zpIndustryWork__kind">' . esc_html($kind) . '</p><h3>' . esc_html($item['brand']) . '</h3><p class="zpIndustryWork__scope">' . esc_html($item['scope'][$lang]) . '</p><p class="zpIndustryWork__why">' . esc_html($item['why'][$lang]) . '</p><div class="zpIndustryWork__actions"><a href="' . esc_url($url) . '">' . ($english ? 'View the project' : 'Zobacz realizację') . '<span aria-hidden="true"> ↗</span></a>';
        if (!empty($found['live']) && empty($found['liveGone'])) { $cards .= '<a href="' . esc_url($found['live']) . '" target="_blank" rel="noopener">' . ($english ? 'Client website' : 'Strona klienta') . '<span aria-hidden="true"> ↗</span></a>'; }
        $cards .= '</div></div></article>';
    }
    if ($cards === '') { return ''; }
    return '<section class="zpIndustryWork" id="zpIndustryWork" data-zp-industry-work="1" aria-labelledby="zpIndustryWorkTitle"><div class="zpIndustryWork__inner"><header class="zpIndustryWork__head"><div><p class="zpIndustryWork__kicker">' . (!empty($spec['functional']) ? ($english ? 'Solutions from our actual work' : 'Rozwiązania z naszych realizacji') : ($english ? 'Selected project work' : 'Wybrane realizacje')) . '</p><h2 id="zpIndustryWorkTitle">' . $heading . '</h2></div><p class="zpIndustryWork__lead">' . esc_html($spec['lead'][$lang]) . '</p></header><div class="zpIndustryWork__grid" data-zp-project-count="' . $index . '">' . $cards . '</div><footer class="zpIndustryWork__footer"><p>' . ($english ? 'Plan the right scope for your business.' : 'Zaplanuj zakres dopasowany do swojej firmy.') . '</p><a href="' . esc_url(zp_industry_work_url_20261015('/studio-wyceny/', $english)) . '">' . ($english ? 'Discuss your project' : 'Omów projekt') . '<span aria-hidden="true"> ↗</span></a></footer></div></section>';
}
function zp_industry_work_document_20261015(string $html, string $source, bool $english): string {
    if (!isset(zp_industry_work_plan_20261015()[$source]) || !function_exists('zp_coverage_section_20261015') || zp_coverage_section_20261015($html, 'zpIndustryWork')) { return $html; }
    $faq = zp_coverage_section_20261015($html, 'faq'); if (!$faq) { return $html; }
    $markup = zp_industry_work_markup_20261015($source, $english); if ($markup === '') { return $html; }
    $aliases = '';
    // Replace the generic website portfolio on these eight industry variants only.
    foreach (['realizacje','portfolio'] as $id) {
        $range = zp_coverage_section_20261015($html, $id);
        if ($range) { $html = substr($html, 0, $range[0]) . substr($html, $range[1]); $aliases .= '<span id="' . $id . '" class="zpIndustryWork__anchor" aria-hidden="true"></span>'; }
    }
    $guide = function_exists('zp_seo_content_pages') ? (zp_seo_content_pages()[$source]['guide']['id'] ?? '') : '';
    $at = $guide !== '' ? zp_coverage_section_20261015($html, $guide) : null;
    if (!$at) { $at = zp_coverage_section_20261015($html, 'faq'); }
    return $at ? substr($html, 0, $at[0]) . $aliases . $markup . substr($html, $at[0]) : $html;
}
add_filter('zp_service_widgets_document', static function (string $html): string {
    return zp_industry_work_document_20261015($html, zp_industry_work_source_20261015(), function_exists('zp_seo_plan_is_en') && zp_seo_plan_is_en());
}, 5);
